INSERT INTO DEDUCTION_TYPE (
    TAX_YEAR, TYPE_CODE, TYPE_NAME, DEDUCTION_KIND,
    RATE, LIMIT_AMOUNT, SALARY_MIN, SALARY_MAX,
    CATEGORY_ID, PAY_METHOD, SOURCE_NOTE, UPDATED_AT, UPDATED_BY
) VALUES (
    #{dto.taxYear}, #{dto.code}, #{dto.name}, #{dto.deductionKind},
    #{dto.rate}, #{dto.limitAmount}, #{dto.salaryMin}, #{dto.salaryMax},
    #{dto.categoryId}, #{dto.payMethod}, #{dto.sourceNote}, SYSDATE, #{updatedBy}
)

INSERT INTO TAX_BRACKET (
    TAX_YEAR, BRACKET_TYPE, LOWER_AMOUNT, UPPER_AMOUNT,
    RATE, BASE_AMOUNT, SOURCE_NOTE, UPDATED_AT, UPDATED_BY
) VALUES (
    #{dto.taxYear}, #{dto.code}, #{dto.lowerAmount}, #{dto.upperAmount},
    #{dto.rate}, #{dto.baseAmount}, #{dto.sourceNote}, SYSDATE, #{updatedBy}
)

INSERT INTO TAX_BRACKET (
    TAX_YEAR, BRACKET_TYPE, LOWER_AMOUNT, UPPER_AMOUNT,
    RATE, BASE_AMOUNT, SOURCE_NOTE, UPDATED_AT, UPDATED_BY
)
SELECT
    #{targetYear}, BRACKET_TYPE, LOWER_AMOUNT, UPPER_AMOUNT,
    RATE, BASE_AMOUNT, SOURCE_NOTE, SYSDATE, #{updatedBy}
FROM TAX_BRACKET
WHERE TAX_YEAR = #{sourceYear}
